  const plazaSend = o => { try { return !!(S.L && S.L.net && S.L.net.send(o)); } catch { return !1; } };
  // 目前的遠征（不在遠征裡 → F 是 null）
  const env = () => { try { return (S.hooks && S.hooks.env && S.hooks.env()) || {}; } catch { return {}; } };
  // 遠征中送訊息給伺服器：組隊走組隊連線、單人走在線狀態連線
  const expSend = o => { try { const E = env(), ws = E.ft && E.ft.link ? E.ft.link.ws : E.gl ? E.gl.ws : null; if (ws && ws.readyState === 1) { ws.send(JSON.stringify(o)); return !0; } } catch {} return !1; };
